-- V003: Alpha 2 P01 - wallet transaction records.
--
-- One row per change to one wallet's balance. A cash top-up is one CREDIT row.
-- Later phases add more types (e.g. CARD_TOP_UP, TRANSFER_IN, TRANSFER_OUT) and
-- statuses (e.g. PENDING) by widening the CHECK lists below in a new migration;
-- a transfer will be written as one DEBIT row and one CREDIT row.
--
-- amount is always positive; direction says whether it was added or removed.
-- balance_after is the wallet balance right after this transaction (audit trail).
-- request_id is generated by the app once per confirmation screen; the UNIQUE
-- constraint makes repeating the same request harmless (no second credit).
-- created_at is stored in UTC by the application.
CREATE TABLE wallet_transactions (
    transaction_id    BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    wallet_id         BIGINT UNSIGNED NOT NULL,
    transaction_type  VARCHAR(30)     NOT NULL,
    direction         VARCHAR(6)      NOT NULL,
    amount            DECIMAL(15, 2)  NOT NULL,
    balance_after     DECIMAL(15, 2)  NOT NULL,
    status            VARCHAR(20)     NOT NULL,
    request_id        VARCHAR(36)     NOT NULL,
    created_at        DATETIME        NOT NULL,

    CONSTRAINT pk_wallet_transactions PRIMARY KEY (transaction_id),
    CONSTRAINT fk_wallet_transactions_wallet FOREIGN KEY (wallet_id) REFERENCES wallets (wallet_id),
    CONSTRAINT uq_wallet_transactions_request UNIQUE (request_id),
    CONSTRAINT chk_wallet_transactions_type CHECK (transaction_type IN ('CASH_TOP_UP')),
    CONSTRAINT chk_wallet_transactions_direction CHECK (direction IN ('CREDIT', 'DEBIT')),
    CONSTRAINT chk_wallet_transactions_top_up_is_credit
        CHECK (transaction_type <> 'CASH_TOP_UP' OR direction = 'CREDIT'),
    CONSTRAINT chk_wallet_transactions_amount_positive CHECK (amount > 0),
    CONSTRAINT chk_wallet_transactions_balance_after CHECK (balance_after >= 0),
    CONSTRAINT chk_wallet_transactions_status CHECK (status IN ('COMPLETED')),
    INDEX idx_wallet_transactions_wallet (wallet_id, transaction_id)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci;
